# Let's look at the specific implementations for each requirement
with open('parse.py', 'r') as f:
    lines = f.readlines()

# R1: letters matcher
print("=== R1: letters matcher ===")
for i, line in enumerate(lines):
    if 'letters' in line.lower() and ('type' in line.lower() or 'matcher' in line.lower()):
        print(f"  {i+1}: {line.rstrip()}")

